import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CQxpk36T.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/developpement/architecture.md","filePath":"en/developpement/architecture.md","lastUpdated":1793574169000}'),d={name:"en/developpement/architecture.md"};function n(r,e,c,i,l,p){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>TypeScript, React 19, <a href="https://r3f.docs.pmnd.rs" target="_blank" rel="noreferrer">React Three Fiber</a> (three.js), Vite, Zustand. No texture to load: everything is generated, geometry and patterns (in GLSL).</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proprietes/&lt;name&gt;/         index.ts: { propriete, site, plans, retouches }  ← @propriete alias (vite.config.ts)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/model/                 types + loaded property, edits applied: PROPERTY, site, PLANS, BOUNDS</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/scene/facade.ts        layout: resolved sections, openings, doors, windows (LAYOUTS)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/scene/*.tsx            rendering: buildings, facades, diorama, sky, life, interiors</span></span>
<span class="line"><span>src/ui/*.tsx               2D interface on top of the canvas</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/ha/                    Home Assistant states (WebSocket) or demo simulator</span></span></code></pre></div><p>The engine knows no property in particular: it reads the package chosen by the <code>PROPRIETE</code> variable (<code>.env.local</code>), <code>proprietes/exemple</code> by default. Tests and page checks always use the example (<code>.env.test</code>, <code>.env.e2e</code>).</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Folder</th><th>Purpose</th></tr></thead><tbody><tr><td><code>src/model/</code></td><td>Description schema (<code>property.ts</code>, <code>plans.ts</code>, <code>site.ts</code>), editor edits (<code>retouches.ts</code>) and loaded package (<code>loaded.ts</code>)</td></tr><tr><td><code>src/scene/</code></td><td>3D scene. <code>geometry.ts</code>: sections, skewed gables, cut walls, roofs, valleys; <code>facade.ts</code>: where to cut and place; <code>Building</code>, <code>Facades</code>, <code>Interior</code>, <code>Diorama</code>, <code>Enclosures</code>, <code>Cars</code>, <code>Life</code>, <code>Sky</code>, <code>Solar</code>: rendering; <code>CameraRig</code>, <code>Lighting</code>; <code>Ghost</code>: fading and cutting of other buildings; <code>Editor</code>: editor previews; <code>windowStates</code>: open windows and roller shutters from HA; <code>roomLamps.ts</code>: ceiling lights of lit rooms; <code>tap.ts</code>: tap tolerance</td></tr><tr><td><code>src/scene/bake/</code></td><td>Precomputed lighting (ambient occlusion, lanterns) in a Web Worker, kept in IndexedDB</td></tr><tr><td><code>src/ui/</code></td><td>Top bar, tabs, summary, building panel, editor, settings, time, weather, placement; <code>dashboard/</code>: Tableau tab; <code>energy/</code>: Énergie tab; <code>controls.tsx</code>: shared controls</td></tr><tr><td><code>src/ha/</code></td><td>WebSocket connection to HA, demo simulator, shared state (Zustand), pending commands</td></tr><tr><td><code>src/weather/</code>, <code>src/solar/</code></td><td>Live weather (Open-Meteo), solar production</td></tr><tr><td><code>src/energy/</code></td><td>The day&#39;s balance and totals (<code>model.ts</code>, pure functions), demo simulation, HA history, Open-Meteo forecast</td></tr><tr><td><code>src/state/</code></td><td>Interface state (selection, simulated time, quality) and editor draft</td></tr><tr><td><code>tools/site/</code></td><td>Land: IGN land registry (Python) or hand description (Node)</td></tr><tr><td><code>deploy/</code></td><td>Caddy container serving <code>dist/</code></td></tr><tr><td><code>e2e/</code></td><td>Checks of the real page (Playwright)</td></tr><tr><td><code>scripts/media/</code></td><td>Demo film and screenshots</td></tr><tr><td><code>docs/</code></td><td>This site (VitePress), French at the root, English in <code>docs/en/</code></td></tr></tbody></table><h2 id="home-assistant" tabindex="-1">Home Assistant <a class="header-anchor" href="#home-assistant" aria-label="Permalink to &quot;Home Assistant&quot;">​</a></h2><p><code>src/ha/connection.ts</code> opens the connection with <a href="https://github.com/home-assistant/home-assistant-js-websocket" target="_blank" rel="noreferrer">home-assistant-js-websocket</a>: Home Assistant&#39;s OAuth login, tokens kept in the browser, subscription to states and registries (Areas, devices, entities). When the page comes back to the foreground, the network returns or a cached page is reopened, a <code>ping</code> checks the connection and restarts it if needed.</p><p><code>src/ha/store.ts</code> is the shared state (Zustand): entities, Areas, entity → Area, and a <strong>common interface</strong> (<code>Backend</code>) implemented by both the connection and the demo simulator (<code>demo.ts</code>). Sent commands are marked &quot;pending&quot; until the entity&#39;s state changes, or six seconds: that&#39;s what makes tiles pulse.</p><h2 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h2><p>In-page edits are a draft (<code>src/state/editor.ts</code>, kept in the browser); each edited building is replaced by a preview of its volume while editing. On save, <code>proprietes/&lt;name&gt;/retouches.json</code> is written by the development server (a <code>vite.config.ts</code> plugin) or downloaded. The package imports it if it exists, and <code>src/model/loaded.ts</code> applies it on top of the description and the land (<code>applyRetouches</code>): the rest of the engine only sees the result.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>Interface text and comments in French, identifiers in English.</li><li>LF line endings (<code>.gitattributes</code>, <code>.editorconfig</code>).</li><li>A personal property never goes into the repository: <code>proprietes/*</code> is ignored, except the example.</li></ul>`,14)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
